import * as THREE from 'three';
import {OrbitControls} from '../../../assets/OrbitControls.js';
const $=id=>document.getElementById(id),host=$('canvas'),scene=new THREE.Scene();scene.background=new THREE.Color('#ffffff');
const camera=new THREE.PerspectiveCamera(38,1,.1,2000);camera.up.set(0,0,1);const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.appendChild(renderer.domElement);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(59.5,0,25);controls.enableDamping=true;
const grid=new THREE.GridHelper(300,30,0xd8e0eb,0xe8edf4);grid.rotation.x=Math.PI/2;grid.position.set(59.5,0,-.2);scene.add(grid);
const colors=[0x8293a7,0xee840b,0xd12e86,0xb9c5ce],cache={},objects=[];let active=null,token=0;
function resize(){const {width,height}=host.getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(host);
function view(kind){const positions={iso:[230,-230,185],top:[59.5,-.001,300],bottom:[59.5,-.001,-270],side:[59.5,-300,35]};camera.position.set(...positions[kind]);controls.target.set(59.5,0,25);controls.update()}view('iso');for(const k of ['iso','top','bottom','side'])$(k).onclick=()=>view(k);
async function read(name){if(cache[name])return cache[name];const response=await fetch(`${name}.paths.json.gz?v=1`);if(!response.ok)throw Error(`Could not load ${name} slice`);const d=await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).json();cache[name]=d;return d}
function update(){if(!active)return;const i=Math.min(active.layers.length-1,+$('layer').value-1),mode=$('mode').value;$('layerLabel').textContent=`${i+1} / ${active.layers.length} · Z ${active.layers[i].z.toFixed(1)} mm`;objects.forEach((o,g)=>{const from=mode==='single'?(i?o.userData.ends[i-1]:0):0,to=mode==='all'?o.userData.ends.at(-1):o.userData.ends[i];o.geometry.setDrawRange(from,to-from);o.visible=g===0?$('model').checked:g===3?$('infill').checked:$('supports').checked});}
async function load(){const t=++token;$('loading').hidden=false;$('loading').textContent='Loading slicer paths…';try{const d=await read($('version').value);if(t!==token)return;active=d;for(const o of objects){scene.remove(o);o.geometry.dispose();o.material.dispose()}objects.length=0;for(let group=0;group<4;group++){const n=d.layers.reduce((n,l)=>n+l.paths[group].length/2,0),vertices=new Float32Array(n*3),ends=[];let at=0;for(const l of d.layers){for(let j=0;j<l.paths[group].length;j+=2){vertices[at++]=l.paths[group][j];vertices[at++]=l.paths[group][j+1];vertices[at++]=l.z}ends.push(at/3)}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(vertices,3));const o=new THREE.LineSegments(geometry,new THREE.LineBasicMaterial({color:colors[group],transparent:true,opacity:group===0?.45:group===3?.2:1,depthWrite:group===1||group===2}));o.userData.ends=ends;objects.push(o);scene.add(o)}$('layer').max=d.layers.length;const m=d.meta;$('stats').textContent=`${m.support_grams.toFixed(1)} g supports · ${m.estimated_grams.toFixed(1)} g total · ${Math.floor(m.estimated_seconds/3600)}h ${Math.round(m.estimated_seconds%3600/60)}m estimated`;update();$('loading').hidden=true;window.sliceViewer={data:d,objects,scene,camera,controls,update};}catch(e){$('loading').textContent=e.message}}
for(const id of ['layer','mode','model','supports','infill'])$(id).oninput=update;$('version').onchange=load;document.querySelectorAll('[data-z]').forEach(b=>b.onclick=()=>{$('layer').value=Math.round(+b.dataset.z/.2);$('mode').value='below';update()});
function animate(){requestAnimationFrame(animate);controls.update();renderer.render(scene,camera)}animate();load();
Promise.all([read('before'),read('after')]).then(([a,b])=>{const fmt=(v)=>v.toFixed(1)+' g';let rows=[['Support material',a.meta.support_grams,b.meta.support_grams],['Total material',a.meta.estimated_grams,b.meta.estimated_grams]];for(const key of Object.keys(a.meta.support_regions_grams))rows.push([`Supports: ${key}`,a.meta.support_regions_grams[key],b.meta.support_regions_grams[key]||0]);$('comparison').innerHTML='<table><thead><tr><th>Measure</th><th>Previous</th><th>Revised</th></tr></thead><tbody>'+rows.map(([label,x,y])=>`<tr><td>${label}</td><td>${fmt(x)}</td><td>${fmt(y)}</td></tr>`).join('')+'</tbody></table>'}).catch(e=>{$('comparison').textContent=e.message});
